// The tray calls window.pasteget.show() with what to display (desktop/tray/src/pairing.rs).
// Text from devices and errors goes in with textContent only; errors come translated.
"use strict";

let countdown = null;

// "4:59"
function clock(secs) {
  const minutes = Math.floor(secs / 60);
  const seconds = String(secs % 60).padStart(2, "0");
  return `${minutes}:${seconds}`;
}

// Says when the code shown is replaced, every second, until `secs` have passed.
function countDown(secs) {
  const renews = document.getElementById("renews");
  const ends = Date.now() + secs * 1000;
  const tick = () => {
    const left = Math.max(0, Math.round((ends - Date.now()) / 1000));
    renews.textContent = window.pastegetFormat("pairRenews", "A new code comes in {time}.", {
      time: clock(left),
    });
  };
  stopCountdown();
  tick();
  countdown = setInterval(tick, 1000);
}

function stopCountdown() {
  if (countdown !== null) clearInterval(countdown);
  countdown = null;
  document.getElementById("renews").textContent = "";
}

window.pasteget = {
  show(view) {
    const code = document.getElementById("code");
    const status = document.getElementById("status");
    status.className = "status";
    switch (view.kind) {
      case "preparing":
        stopCountdown();
        code.className = "code waiting";
        code.textContent = window.pastegetText("pairPreparing", "Preparing the code…");
        status.textContent = "";
        break;
      case "code":
        code.className = "code";
        // The SVG is generated by the tray from the pairing link, never from a peer.
        code.innerHTML = view.svg;
        // Why the last code was replaced early (already translated), or the usual advice.
        if (view.note) {
          status.className = "status bad";
          status.textContent = view.note;
        } else {
          status.textContent = window.pastegetText(
            "pairOnce",
            "The code works once. Keep it to yourself: whoever scans it first is paired.",
          );
        }
        countDown(view.secs);
        break;
      case "attempt-failed":
        status.className = "status bad";
        status.textContent = view.text;
        break;
      case "paired":
        stopCountdown();
        code.className = "code done";
        code.textContent = "✓";
        status.className = "status ok";
        status.textContent = window.pastegetFormat("pairPaired", "Paired with {name}.", {
          name: view.text,
        });
        break;
      case "error":
        stopCountdown();
        code.className = "code failed";
        code.textContent = "!";
        status.className = "status bad";
        status.textContent =
          view.text + " " + window.pastegetText("pairRetrying", "Trying again in a few seconds…");
        break;
    }
  },
};

document.addEventListener("DOMContentLoaded", () => {
  const releases = document.getElementById("releases");
  window.pastegetCopyable(releases, document.getElementById("copy_releases"));
  window.pastegetAppInfo().then((info) => {
    if (info) releases.value = info.releases;
  });
});
